css='''*{box-sizing:border-box}body{margin:0;background:#edf0ec;color:#183142;font:16px/1.75 system-ui,-apple-system,sans-serif}main{max-width:1500px;margin:auto;padding:28px 24px 70px}nav,.links{display:flex;gap:20px;flex-wrap:wrap}a{color:#08617e}h1{font-size:clamp(28px,4vw,46px);line-height:1.22;margin:28px 0 18px}h2{margin-top:48px}p{max-width:1000px}figure{margin:20px 0;background:#fff;border-radius:8px;overflow:hidden}img{display:block;width:100%;height:auto}figcaption{padding:10px 14px;font-size:14px;color:#47616f}.turnaround{display:grid;grid-template-columns:repeat(3,1fr);gap:14px}.turnaround figure{margin:0}.turnaround img{aspect-ratio:2/3;object-fit:contain}.pair{display:grid;grid-template-columns:1fr 1fr;gap:16px}.note{border-left:4px solid #df8b2c;padding:12px 18px;background:#fff7e8}details{margin-top:28px;padding:18px;background:#e0e8e5}summary{font-weight:600;cursor:pointer}video{display:block;width:100%;max-height:650px;background:#3b3f41}table{border-collapse:collapse;width:100%;background:white}td,th{padding:12px;border-bottom:1px solid #d2dedc;text-align:left}@media(max-width:750px){.turnaround,.pair{grid-template-columns:1fr}main{padding:20px 14px}.turnaround img{max-height:1100px}}'''
body='<nav><a href="index.html">返回素材总览</a><a href="#robot">人形三视</a><a href="#head">头部颏甲</a><a href="#vehicle">车形三视</a><a href="#structure">可变结构</a></nav><h1>货柜领袖：指定头部、长腿身形与可变结构</h1><p>以用户附图的头型和原眼形为准，新增短厚前凸的勇者式颏甲。头部纵向体积与整机头身大小分别处理，身体沿用原未来货车人形的长腿尺度。</p><h2 id="robot">人形正、侧、背</h2><div class="turnaround">'+''.join(fig(byid[k],c) for k,c in [('FRONT','正面 · 原长腿身形与恢复纵向体积的头部'),('SIDE','左侧 · 颏甲前凸、四个轮位、薄背架'),('REAR','背面 · 三片货台背架与侧向胎缘')])+'</div><h2 id="head">头部：保留附图比例，增加颏甲识别点</h2>'+fig(byid['HEAD_OPTIONS'],'原眼形与双侧钝头天线保留；下巴增加短厚五边形前凸颏甲')+'<details><summary>用户指定的原头稿与比例来源</summary>'+fig({'file':selection['selected_copy'],'role':'用户明确选定的原头部源图'})+'<p>整机头身比以原未来人形为准；原头部认可不扩大为新增颏甲、三视或模型验收。</p><a href="M11-head-selected-and-turnaround-r6.json">指定原图记录</a></details><h2 id="vehicle">车形前、侧、背</h2>'+fig(byid['VEHICLE'],'四轴刚性底盘、单个独立货柜、柱侧摄像头后视')+'<h2 id="structure">头部与天线收纳</h2><p>先打开分体舱盖，天线由耳后铰链向后折入导槽，头部下降并沿短滑轨退入驾驶室后方的独立设备仓。颏甲前侧和天线尾端各留收纳空间，仓体与驾驶空间分开。</p>'+fig(byid['HEAD_MECHANISM'],'展开 → 天线后折 → 独立头仓收纳')+'<h2>轮架、腿架与货台分件</h2>'+fig(byid['CHASSIS_MECHANISM'],'A 前两轴轮架转位 · B 后车架与长腿/足跟 · C 三片货台折成浅背架')+'<table><thead><tr><th>车形部件</th><th>人形去向</th><th>结构处理</th></tr></thead><tbody>'
for row in [('前两轴轮组','每侧肩后1轮、前臂外后1轮','左右独立轮架、翻转臂和锁止套'),('后双轴与侧梁','每侧长腿及小腿2轮','膝/踝分开，内侧撑杆和足跟锁止'),('三片货台','浅背架','交替铰链折叠，角锁保留'),('后防钻梁','左右足跟/足掌','先展开脚板；前轮转位放在脚板支撑建立之后'),('独立货柜','卸在地面','保持完整体积，不带入背包或缩水')]:body+='<tr>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>'
body+='</tbody></table><details><summary>查看头仓同件草模与核对范围</summary><p>这是归一化的头部包络研究，四状态使用同一颗头、两根天线和同一组舱盖。它只核对矩形头仓收纳余量，不是整机受力、驾驶室容量或完整碰撞认证。</p><video controls preload="metadata" poster="M11-head-bay-r7/04-stored-hatch-closed.png"><source src="M11-head-bay-r7/M11-head-bay-motion-r7.mp4" type="video/mp4">请打开<a href="M11-head-bay-r7/M11-head-bay-motion-r7.mp4">头仓草模视频</a>。</video><div class="pair">'+fig({'file':'M11-head-bay-r7/01-deployed.png','role':'草模：头部展开'})+fig({'file':'M11-head-bay-r7/04-stored-hatch-closed.png','role':'草模：头部收纳、舱盖闭合'})+'</div><p class="links"><a href="M11-head-bay-r7/M11-head-bay-r7.blend">可编辑头仓草模</a><a href="M11-head-bay-r7/head-bay-check.json">实际检查范围与余量</a></p></details><p class="note">本轮补齐的是三视与结构设计稿。各视角仍是独立绘制；详细装配、整机重心/受力和全程碰撞需要后续模型校核。</p><details><summary>源稿、实际提示词与检查记录</summary><p class="links"><a href="M11-turnaround-structure-production-r7.json">当前7张源稿与作者观察</a><a href="M11-turnaround-structure-prompts-r7.json">内置生图提示词组</a><a href="M11-head-aspect-chin-direction-r7.json">用户头高与颏甲要求</a><a href="M11-turnaround-structure-verification-r7.json">文件核对</a><a href="M11-heroic-antenna-r5.html">此前头稿历史</a></p><p>具体新稿尚未采用，未替换游戏运行资产。</p></details>'
